const fapsOutcomes=[['Accounting principles',5],['Advanced double-entry bookkeeping',10],['Acquisition and disposal of non-current assets',10],['Depreciation',10],['Period end adjustments',10],['Trial balance and extended trial balance',15],['Sole trader and partnership financial statements',20],['Profitability ratios',10],['Incomplete information',10]];
function courseDate(date){return new Date(date+'T12:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'Europe/London'})}
function selectedWeek(){if(state.studyWeek&&fapsWeeks.some(w=>w.week===state.studyWeek))return fapsWeeks.find(w=>w.week===state.studyWeek);let date=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/London',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());let part=x=>date.find(p=>p.type===x).value;let today=part('year')+'-'+part('month')+'-'+part('day');return [...fapsWeeks].reverse().find(w=>w.date<=today)||fapsWeeks[0]}
function courseWeekControl(){let w=selectedWeek();return `<label class="week-select">Study week<select id="study-week">${fapsWeeks.map(x=>`<option value="${x.week}" ${w.week===x.week?'selected':''}>Week ${x.week} · ${courseDate(x.date)}</option>`).join('')}</select></label>`}
function courseBanner(){let w=selectedWeek();return `<section class="course-banner"><div><span class="eyebrow">AAT LEVEL 3 · FAPS</span><h2>Week ${w.week}: ${w.label}</h2><p>Week commencing ${courseDate(w.date)}${w.note?' · '+w.note:''}</p><a class="text-button" href="#course">View your course roadmap →</a></div>${courseWeekControl()}</section>`}
function roadmap(){let id=location.hash.split('/')[1]||'FAPS',m=courseModules.find(m=>m.id===id)||courseModules[0];return `<span class="eyebrow">YOUR COLLEGE COURSE · 2026–27</span><h1>Learning, in the order you learn it.</h1><p>Topic headings and dates follow your evening college scheme of learning.</p><div class="module-tabs">${courseModules.map(x=>`<a href="#course/${x.id}" class="${m.id===x.id?'selected':''}"><strong>${x.id}</strong><span>${x.name}</span></a>`).join('')}</div><section class="card"><div class="section-heading"><div><span class="eyebrow">${m.id}</span><h2>${m.name}</h2></div><span class="tag">${m.status}</span></div><p>College examination: <strong>${m.exam}</strong>. Dates follow the supplied schedule; check college communications for changes.</p>${m.id==='FAPS'?'<div class="notice">Practice is available for every FAPS topic heading below. Each topic lists the skills currently supported; full financial statements and ETB worksheets are still to be added.</div>':'<div class="notice">These headings are your course roadmap. Practice for this unit has not yet been developed; add its workbook when available.</div>'}<div class="roadmap-list">${m.weeks.map(w=>`<article class="roadmap-row"><div><strong>Week ${w.week}</strong><small>w/c ${courseDate(w.date)}</small></div><div><h3>${w.label}</h3>${m.id!=='FAPS'&&w.label.includes(';')?`<ul class="roadmap-bullets">${w.label.split(';').map(s=>`<li>${s.trim()}</li>`).join('')}</ul>`:''}${w.note?`<p>${w.note}</p>`:''}${m.id==='FAPS'?`<div class="topic-links">${(w.topics?.length?w.topics:courseTopics.filter(t=>t.week).map(t=>t.id)).map(id=>{let t=courseTopics.find(t=>t.id===id);return `<button class="secondary" data-topic="${id}">${t.name} →</button>`}).join('')}</div>`:''}</div></article>`).join('')}</div></section>${m.id==='FAPS'?`<section class="card" style="margin-top:22px"><h2>AAT learning outcomes</h2><p>Assessment weightings in the supplied specification, version 5.13. These percentages describe the assessment, not your mastery.</p><table><thead><tr><th>Outcome</th><th>Area</th><th>Weighting</th></tr></thead><tbody>${fapsOutcomes.map((o,i)=>`<tr><td>${i+1}</td><td>${o[0]}</td><td>${o[1]}%</td></tr>`).join('')}</tbody></table></section>`:''}<section class="card" style="margin-top:22px"><h2>How the Lab follows your course</h2><p><strong>Teaching guide:</strong> Kaplan FAPS Integrated Workbook (2022), with chapter and printed-page references on each topic.<br><strong>Topic sequence:</strong> your Summarised Scheme of Learning, 2026–27.<br><strong>Technical scope:</strong> AAT Level 3 Diploma in Accounting specification v5.13, September 2026.</p><p>Questions and explanations are original independent practice. Workbook pages and exercises are not reproduced. Terminology follows the supplied sources; diminishing balance is also called reducing balance, and allowance for doubtful receivables is also described as allowance for doubtful debts in the workbook.</p></section>`}
function courseReference(t){if(t.priorLearning)return `<details class="course-reference"><summary>Prior learning · ${t.name}</summary><p>Original bookkeeping refresher questions. These are separate from your Kaplan FAPS workbook chapters and college timetable.</p><ul>${t.skills.map(s=>`<li>${s}</li>`).join('')}</ul><p>${t.id==='vat'?'VAT questions state the applicable rate and recovery assumptions.':'Payroll questions supply deduction and contribution amounts; statutory rates and tax codes are not calculated.'}</p><p><strong>Further scope:</strong> ${t.next}.</p><p><a href="${t.id==='vat'?'https://www.gov.uk/charge-reclaim-record-vat':'https://www.gov.uk/running-payroll/deductions'}" target="_blank" rel="noopener">HMRC background guidance</a></p></details>`;return `<details class="course-reference"><summary>Course link · Kaplan chapter ${t.chapter} · AAT ${t.refs}</summary><p>FAPS Integrated Workbook: chapter ${t.chapter}, printed pages ${t.pages}. AAT FAPS scope references ${t.refs} (specification v5.13).</p><strong>Practice in this topic</strong><p>Calculations and choices are mixed with definition and scenario matching, suggested workflow ordering and statement reviews. Matching also supports clicking and dropdowns.</p><ul>${t.skills.map(s=>`<li>${s}</li>`).join('')}</ul><p><strong>Still to add:</strong> ${t.next}.</p></details>`}
function makeNumber(id,skill,question,value,explanation,hint,unit='£',meta={}){return {id,skill,question,kind:'number',correctValue:round(value),unit,explanation,hint,answered:false,meta}}
function makeChoice(id,skill,question,correct,wrong,explanation,hint,meta={}){return {id,skill,question,kind:'choice',options:shuffled([correct,...wrong].map(label=>({label,correct:label===correct}))),explanation,hint,answered:false,meta}}
function courseGenerate(id,variant){let t=courseTopics.find(t=>t.id===id),v=Number.isInteger(variant)?variant:rand(0,3),a=rand(20,70)*100,b=rand(2,8)*100,c=rand(1,5)*100,d=rand(2,6),q;
 const N=(skill,question,value,explanation,unit='£',meta={})=>makeNumber(id,skill,question,value,explanation,t.hint,unit,meta),C=(skill,question,correct,wrong,explanation,meta={})=>makeChoice(id,skill,question,correct,wrong,explanation,t.hint,meta);
 if(id==='capital'){
  if(v===0)q=C('Classify expenditure',`A business pays ${money(b)} for a routine service of an existing delivery van. The service restores normal performance; it does not improve the van. How should this be classified?`,'Revenue expenditure',['Capital expenditure','Drawings','Capital introduced'],'Routine maintenance is an expense in the statement of profit or loss. It does not create or improve a non-current asset.');
  if(v===1)q=N('Calculate asset cost',`A machine costs ${money(a)}. Delivery costs ${money(b)} and installation costs ${money(c)} are needed to get it ready for use. An annual maintenance contract costs ${money(240)}. Ignore VAT. What amount is capitalised?`,a+b+c,`Capitalised cost = purchase ${money(a)} + delivery ${money(b)} + installation ${money(c)} = ${money(a+b+c)}. The annual maintenance contract is revenue expenditure.`, '£',{a,b,c,formula:'sum'});
  if(v===2)q=C('Capitalisation policy',`A small item of office equipment costs ${money(80)} and will last three years. The business has a policy to expense individual items below ${money(150)}. What is the appropriate treatment?`,'Expense it under the capitalisation policy',['Capitalise it regardless of policy','Record it as drawings','Treat it as an irrecoverable debt'],'Apply the stated materiality-based capitalisation policy: the item is below the threshold.');
  if(v===3)q=C('Effect of misclassification',`Equipment costing ${money(a)} is incorrectly charged entirely to repairs expense. Ignore depreciation and VAT. What is the effect?`,'Profit and non-current assets are understated',['Profit and non-current assets are overstated','Profit is overstated; assets are understated','No effect on profit or assets'],'The expense is too high and the asset has not been recognised. Correcting the entry increases both profit and non-current assets.');
 }
 if(id==='principles'){
  const bank=[['Accruals principle','A December electricity bill arrives in January. Why is the December expense recognised in December?','Accruals',['Money measurement','Going concern','Business entity'],'Expenses are recognised when incurred, not simply when paid.'],['Business entity','The owner’s personal holiday is paid from the business bank account. Which principle means it should be recorded as drawings, rather than a business expense?','Business entity',['Consistency','Materiality','Timeliness'],'The business and the owner are treated separately for accounting purposes.'],['Information quality','An accountant checks that all transactions are recorded completely, neutrally and without material error. Which fundamental characteristic is being supported?','Faithful representation',['Timeliness','Comparability','Verifiability'],'Faithful representation requires information to reflect the transaction faithfully, with completeness, neutrality and freedom from error.'],['Ethical judgement','A manager asks you to leave out a valid expense to meet a profit target. What is the appropriate response?','Use the evidence, record the expense and raise the concern',['Omit it because the manager authorised it','Record it next year without justification','Create an offsetting fictitious sale'],'Integrity and objectivity require accurate reporting. Apply professional scepticism and follow the appropriate escalation process.'],['Going concern','Accounts are prepared on the basis that the business will continue operating for the foreseeable future. Which principle applies?','Going concern',['Money measurement','Prudence','Materiality'],'The going concern basis assumes continuing operations rather than imminent liquidation.'],['Primary users','A lender is reviewing financial statements before granting a loan. What is a main information need?','Ability to pay interest and repay the loan',['The owner’s favourite supplier','Number of social media followers alone','Personal spending of employees'],'Lenders use financial statements to assess repayment capacity and risk.'],['Consistency','A business uses the same depreciation approach from one period to the next, unless a justified change is needed. Which principle does this illustrate?','Consistency',['Business entity','Money measurement','Going concern'],'Consistent treatment helps comparisons between periods. A justified change should be explained.'],['Prudence','A customer balance may not be recovered. Which principle supports a carefully evidenced allowance without deliberately overstating losses?','Prudence',['Business entity','Timeliness','Money measurement'],'Prudence means caution under uncertainty while remaining neutral; it does not justify deliberately biased figures.']];let s=bank[rand(0,bank.length-1)];q=C(...s);
 }
 if(id==='depreciation'){
  a=rand(12,48)*1000;b=rand(1,5)*500;c=rand(3,8);
  if(v===0)q=N('Straight-line: useful life',`A non-current asset costs ${money(a)}, has a residual value of ${money(b)} and a useful life of ${c} years. Calculate a full year’s straight-line depreciation.`,(a-b)/c,`Depreciable amount = ${money(a-b)}. Divide by ${c} years to give ${money((a-b)/c)}.`, '£',{a,b,c,formula:'straight'});
  if(v===1){d=rand(3,10);q=N('Straight-line: pro-rata',`A machine costs ${money(a)} with no residual value. Straight-line depreciation is 20% of cost per year, charged monthly from acquisition. It was bought on the first day of a month and used for ${d} months before year-end. Calculate the charge.`,a*.2*d/12,`${money(a)} × 20% × ${d}/12 = ${money(a*.2*d/12)}. Use the specified monthly policy.`, '£',{a,d,formula:'prorata'})}
  if(v===2){d=[10,15,20,25][rand(0,3)];let opening=a*(1-d/100);q=N('Diminishing balance',`An asset cost ${money(a)}. The policy is ${d}% diminishing balance depreciation for each full year. Calculate the year 2 charge; assume no residual-value constraint.`,opening*d/100,`Year 2 opening carrying amount = ${money(a)} × ${100-d}% = ${money(opening)}. Charge = ${money(opening)} × ${d}% = ${money(opening*d/100)}.`, '£',{a,d,formula:'diminishing'})}
  if(v===3)q=C('Record depreciation','Which journal records depreciation of equipment?','Debit depreciation expense; credit accumulated depreciation — equipment',['Debit equipment; credit bank','Debit accumulated depreciation; credit depreciation expense','Debit drawings; credit equipment'],'Depreciation is an expense in the SPL. Accumulated depreciation is deducted from asset cost in the SFP.');
 }
 if(id==='disposal'){
  a=rand(12,30)*1000;b=rand(3,9)*1000;c=rand(4,18)*1000;
  if(v===0)q=N('Profit or loss on disposal',`An asset cost ${money(a)} and has accumulated depreciation of ${money(b)} at disposal. Proceeds are ${money(c)}. Calculate proceeds less carrying amount: enter a positive profit or a negative loss.`,c-(a-b),`Carrying amount = ${money(a-b)}. Proceeds − carrying amount = ${money(c-(a-b))}, ${c>a-b?'a profit':c<a-b?'a loss':'no profit or loss'}.`, '£',{a,b,c,formula:'disposal'});
  if(v===1)q=C('Remove asset cost',`An asset with original cost ${money(a)} is sold. Which journal removes its cost?`,'Debit disposals; credit non-current asset cost',['Debit bank; credit disposals','Debit non-current asset cost; credit disposals','Debit accumulated depreciation; credit disposals'],'The cost is credited out of the asset account and debited to the disposals account.');
  if(v===2)q=C('Remove accumulated depreciation',`Accumulated depreciation of ${money(b)} relates to an asset being sold. Which journal removes it?`,'Debit accumulated depreciation; credit disposals',['Debit disposals; credit accumulated depreciation','Debit bank; credit depreciation expense','Debit non-current asset cost; credit bank'],'The accumulated depreciation credit balance is removed with a debit; the credit goes to disposals.');
  if(v===3){let newCost=a+5000,trade=b;q=N('Part-exchange funding',`New equipment has a cash price of ${money(newCost)}. The supplier allows ${money(trade)} for the old equipment in part-exchange. Ignore VAT. How much cash is paid?`,newCost-trade,`Cash paid = new asset price ${money(newCost)} − part-exchange allowance ${money(trade)} = ${money(newCost-trade)}. The old asset disposal is accounted for separately.`, '£',{a:newCost,b:trade,formula:'difference'})}
 }
 if(id==='irrecoverable'){
  if(v===0)q=C('Write-off journal',`A customer balance of ${money(b)} is confirmed irrecoverable. Ignore VAT. Which journal writes it off?`,'Debit irrecoverable debt expense; credit receivables ledger control account',['Debit allowance for doubtful receivables; credit bank','Debit receivables ledger control account; credit sales','Debit bank; credit irrecoverable debt expense'],'The write-off removes the receivable and records the expense. The customer’s subsidiary ledger account must also be updated.');
  if(v===1)q=C('Recovery: full entries',`A customer pays ${money(c)} against a debt previously written off. Which pair of journals shows reinstatement followed by receipt?`,'Dr receivables / Cr irrecoverable debt expense; then Dr bank / Cr receivables',['Dr bank / Cr sales; then Dr sales / Cr receivables','Dr expense / Cr receivables; then Dr bank / Cr expense','Dr receivables / Cr bank; then Dr expense / Cr receivables'],'First reinstate the receivable and reverse the expense. Then record the bank receipt against the receivable. The net simplified entry is Dr bank / Cr irrecoverable debt expense.');
  if(v===2)q=N('Net receivables',`Trade receivables before adjustments are ${money(a)}. Write off ${money(b)} as irrecoverable. A closing allowance of ${money(c)} is then required. What net receivables figure appears in the SFP?`,a-b-c,`${money(a)} − write-off ${money(b)} − closing allowance ${money(c)} = ${money(a-b-c)}.`, '£',{a,b,c,formula:'subtract'});
  if(v===3)q=C('Doubtful versus irrecoverable','A customer is late paying and recovery is uncertain, but the debt is not considered wholly irrecoverable. What is the appropriate accounting approach?','Consider an evidenced allowance and retain the customer balance',['Automatically write off the whole balance','Record a new sale','Ignore the uncertainty until cash arrives'],'A doubtful receivable remains outstanding. An allowance reflects uncertainty in its reported net value, based on the available evidence.');
 }
 if(id==='allowance'){
  a=rand(30,90)*1000;b=rand(1,5)*1000;c=rand(1,4)*1000;d=rand(2,5);let eligible=a-b-c,closing=c+eligible*d/100,opening=rand(1,8)*1000;
  if(v===0)q=N('Specific plus general allowance',`Receivables total ${money(a)} before adjustments. Write off ${money(b)}. Make a full specific allowance for a different ${money(c)} balance. Policy requires a ${d}% general allowance on the remaining receivables, excluding that specific balance. Calculate the total closing allowance.`,closing,`Eligible general balance = ${money(a)} − ${money(b)} − ${money(c)} = ${money(eligible)}. General allowance = ${money(eligible*d/100)}. Add the specific allowance ${money(c)}: total ${money(closing)}.`, '£',{a,b,c,d,formula:'specific'});
  if(v===1)q=N('Allowance movement',`The required closing allowance is ${money(closing)}; the opening allowance is ${money(opening)}. Calculate the adjustment: enter a positive increase or a negative decrease.`,closing-opening,`Closing ${money(closing)} − opening ${money(opening)} = ${money(closing-opening)}. An increase is an SPL debit; a decrease is an SPL credit.`, '£',{a:closing,b:opening,formula:'difference'});
  if(v===2)q=C('Decrease journal','The allowance for doubtful receivables must decrease. Which journal records this?','Debit allowance for doubtful receivables; credit allowance adjustment',['Debit allowance adjustment; credit allowance for doubtful receivables','Debit receivables; credit sales','Debit bank; credit allowance adjustment'],'A debit reduces the allowance’s credit balance. The credit to the adjustment account reduces the expense in the SPL.');
  if(v===3)q=N('SFP net receivables',`Trade receivables after write-offs total ${money(a)}. The total closing allowance is ${money(closing)}. What net receivables amount is reported in the SFP?`,a-closing,`Trade receivables ${money(a)} − total allowance ${money(closing)} = ${money(a-closing)}. The allowance does not remove individual customer balances.`, '£',{a,b:closing,formula:'difference'});
 }
 if(id==='bank'){
  if(v===0)q=N('Reconcile a positive balance',`The bank statement shows a positive balance of ${money(a)}. Uncleared lodgements are ${money(b)} and unpresented cheques are ${money(c)}. What balance should agree with the updated cash book?`,a+b-c,`Balance per statement + uncleared lodgements − unpresented cheques = ${money(a)} + ${money(b)} − ${money(c)} = ${money(a+b-c)}.`, '£',{a,b,c,formula:'summinus'});
  if(v===1)q=N('Update the cash book',`The cash book has a debit balance of ${money(a)}. Bank charges of ${money(35)} and a customer receipt of ${money(b)} appear only on the statement. What is the updated cash book balance?`,a-35+b,`Deduct bank charges and add the receipt: ${money(a)} − ${money(35)} + ${money(b)} = ${money(a-35+b)}.`, '£',{a,b,c:35,formula:'summinus'});
  if(v===2)q=N('Overdrawn statement',`The bank statement shows an overdraft of ${money(a)}. Uncleared lodgements are ${money(b)} and unpresented cheques are ${money(c)}. Calculate the reconciled balance, using a negative figure for an overdraft.`,-a+b-c,`Start with −${money(a)}. Add ${money(b)} and subtract ${money(c)} = ${money(-a+b-c)}. The negative result is an overdraft.`, '£',{a:-a,b,c,formula:'summinus'});
  if(v===3)q=C('Reconciling-item classification','A cheque is already recorded as a payment in the cash book but has not yet appeared on the bank statement. How is it treated?','Subtract it from the statement balance in the reconciliation',['Deduct it from the cash book a second time','Add it to the statement balance','Record new income in the cash book'],'It is an unpresented cheque, a timing difference. The cash book already includes the payment.');
 }
 if(id==='control'){
  a=rand(20,50)*1000;b=rand(2,8)*100;c=rand(1,5)*100;
  if(v===0)q=N('Correct RLCA',`The receivables ledger control account has a debit balance of ${money(a)}. Sales returns of ${money(b)} were omitted from the control account but correctly posted to customer accounts. What is the corrected control balance?`,a-b,`Sales returns reduce receivables. Corrected RLCA = ${money(a)} − ${money(b)} = ${money(a-b)}. The subsidiary ledger already includes them.`, '£',{a,b,formula:'difference'});
  if(v===1)q=N('Correct subsidiary total',`The total of customer balances is ${money(a)}. A customer receipt of ${money(b)} was correctly recorded in the RLCA but omitted from the customer’s account. What is the corrected list total?`,a-b,`The customer’s debt must decrease by the receipt: ${money(a)} − ${money(b)} = ${money(a-b)}. Do not change the correct control account.`, '£',{a,b,formula:'difference'});
  if(v===2)q=N('Correct PLCA',`The payables ledger control account has a credit balance of ${money(a)}. A supplier payment of ${money(b)} was omitted from this account but correctly entered in the supplier’s account. What is the corrected amount payable?`,a-b,`The omitted payment reduces the liability: ${money(a)} − ${money(b)} = ${money(a-b)}.`, '£',{a,b,formula:'difference'});
  if(v===3)q=C('Locate the error','A sales daybook total was overstated, but individual customer invoices were entered correctly in the receivables ledger. Which record needs correction?','Receivables ledger control account in the general ledger',['All individual customer accounts','Bank statement','No record; the difference can be ignored'],'The daybook total is posted to the general ledger control account. The individual subsidiary balances are already correct.');
 }
 if(id==='accruals'){
  a=rand(10,30)*120;b=rand(2,5);c=rand(1,4)*100;
  if(v===0)q=N('Expense prepayment',`Annual insurance of ${money(a)} is paid on 1 ${['','','March','April','May','June'][b]} for 12 months. The year ends on 31 December. What expense prepayment is carried forward?`,a*b/12,`${b} months relate to the following year. Prepayment = ${money(a)} × ${b}/12 = ${money(a*b/12)}. It is a current asset.`, '£',{a,b,formula:'months'});
  if(v===1)q=N('Expense with opening adjustments',`Rent paid during the year is ${money(a)}. Opening accrual ${money(b*100)}, opening prepayment ${money(c)}, closing accrual ${money(400)}, closing prepayment ${money(250)}. Calculate rent expense in the SPL.`,a-b*100+c+400-250,`Expense = payments − opening accrual + opening prepayment + closing accrual − closing prepayment. ${money(a)} − ${money(b*100)} + ${money(c)} + ${money(400)} − ${money(250)} = ${money(a-b*100+c+150)}.`, '£',{a,b:b*100,c,formula:'expense'});
  if(v===2)q=C('Accrued income journal',`Commission of ${money(c)} has been earned by year-end but not received. Which journal records it?`,'Debit accrued income; credit commission income',['Debit commission income; credit accrued income','Debit bank; credit prepaid income','Debit drawings; credit commission income'],'Recognise the earned income in the SPL and a current asset for the amount still receivable.');
  if(v===3)q=C('Prepaid income journal',`Rental income of ${money(c)} received in this year relates entirely to next year. Which adjustment is required?`,'Debit rental income; credit prepaid income',['Debit prepaid income; credit rental income','Debit bank; credit rental income again','Debit rental expense; credit accruals'],'Remove the unearned amount from this year’s income and recognise a current liability.');
 }
 if(id==='suspense'){
  if(v===0)q=C('Error of principle',`A cash purchase of equipment for ${money(a)} was debited to repairs expense and credited correctly to bank. Which correction is needed?`,'Debit equipment; credit repairs expense',['Debit equipment; credit suspense','Debit suspense; credit bank','No correction because the trial balance balances'],'Both sides were entered equally, so the trial balance still balances. This is an error of principle and requires reclassification, not suspense.');
  if(v===1)q=C('Missing debit',`A cash rent payment of ${money(b)} was credited correctly to bank but the rent debit was omitted. Suspense was used to balance the trial balance. Which correcting journal clears this error?`,'Debit rent expense; credit suspense',['Debit suspense; credit rent expense','Debit bank; credit rent expense','Debit rent expense; credit bank again'],'The missing debit is posted to rent. The balancing suspense debit is removed by a credit.');
  if(v===2)q=N('Wrong-side posting',`A rent payment of ${money(b)} was credited to rent expense instead of debited. The bank credit was correct. What amount must be debited to rent expense to correct this error?`,b*2,`Reverse the incorrect credit of ${money(b)} and enter the correct debit of ${money(b)}: total debit ${money(b*2)}. The other side is a credit to suspense.`, '£',{a:b,formula:'double'});
  if(v===3)q=C('Trial balance limitations','A purchase invoice is completely omitted from both sides of the accounting records. Will the trial balance totals reveal this error?','No — both the debit and credit are missing',['Yes — debits exceed credits','Yes — credits exceed debits','Only if the invoice is paid in cash'],'Complete omission affects both sides equally. A balanced trial balance is not proof that all transactions are recorded correctly.');
 }
 if(id==='inventory'){
  if(v===0){a=rand(20,50);b=rand(25,60);c=rand(3,10);d=rand(10,40);let val=Math.min(a,b-c)*d;q=N('Lower of cost and NRV',`${d} units cost ${money(a)} each. Expected selling price is ${money(b)} per unit and further selling costs are ${money(c)} per unit. No other costs remain. What is the inventory valuation?`,val,`NRV per unit = ${money(b)} − ${money(c)} = ${money(b-c)}. Lower of cost and NRV = ${money(Math.min(a,b-c))}. Multiply by ${d}: ${money(val)}.`, '£',{a,b,c,d,formula:'nrv'})}
  if(v===1){let cost1=a,nrv1=a-b,cost2=c+1000,nrv2=cost2+300;q=N('Value each item separately',`Item A: total cost ${money(cost1)}, total NRV ${money(nrv1)}. Item B: total cost ${money(cost2)}, total NRV ${money(nrv2)}. Calculate the combined closing inventory valuation.`,nrv1+cost2,`Item A is valued at NRV ${money(nrv1)}; item B at cost ${money(cost2)}. Total ${money(nrv1+cost2)}. Do not offset one item’s excess NRV against another item’s loss.`, '£',{a:nrv1,b:cost2,c:0,formula:'sum'})}
  if(v===2)q=C('Closing inventory journal','Which year-end journal records closing inventory under the periodic inventory approach used in these exercises?','Debit inventory (SFP); credit closing inventory (SPL)',['Debit purchases; credit inventory','Debit closing inventory (SPL); credit inventory (SFP)','Debit drawings; credit bank'],'Closing inventory is an asset and reduces cost of sales for the period.');
  if(v===3)q=C('Effect on profit',`Closing inventory is overstated by ${money(b)}. What is the effect on the financial statements?`,'Profit and current assets are overstated',['Profit and current assets are understated','Profit is understated; current assets are overstated','There is no effect on profit'],'Excess closing inventory reduces cost of sales too much, increasing profit and overstating the inventory asset.');
 }
 if(id==='etb'){
  if(v===0){let rows=[['Prepayments','SFP debit'],['Accruals of expenses','SFP credit'],['Depreciation expense','SPL debit'],['Sales revenue','SPL credit'],['Accumulated depreciation','SFP credit'],['Drawings','SFP debit']];let s=rows[rand(0,rows.length-1)];q=C('Extend a balance',`Which column of a sole trader’s ETB should receive the normal adjusted balance for ${s[0].toLowerCase()}?`,s[1],['SFP debit','SFP credit','SPL debit','SPL credit'].filter(x=>x!==s[1]),`${s[0]} belongs in the ${s[1]} column. Classify the balance before extending it.`)}
  if(v===1)q=C('Profit balancing figure','A sole trader’s ETB shows a profit for the year. In which columns is the balancing profit figure entered?','SPL debit and SFP credit',['SPL credit and SFP debit','SPL debit and SFP debit','SPL credit and SFP credit'],'Profit balances the excess of income over expenses in the SPL debit column and increases capital in the SFP credit column.');
  if(v===2)q=N('Adjust an expense balance',`The rent expense debit balance in the initial trial balance is ${money(a)}. A closing prepayment of ${money(b)} must be recorded. No opening adjustment is involved. What adjusted rent figure extends to the SPL?`,a-b,`Reduce the expense for the amount relating to the next period: ${money(a)} − ${money(b)} = ${money(a-b)}. The prepayment extends to SFP debit.`, '£',{a,b,formula:'difference'});
  if(v===3)q=C('Loss balancing figure','A sole trader’s ETB shows a loss for the year. Which columns receive the balancing loss figure?','SPL credit and SFP debit',['SPL debit and SFP credit','SPL debit and SFP debit','SPL credit and SFP credit'],'A loss balances excess expenses in the SPL credit column and reduces capital in the SFP debit column.');
 }
 if(id==='incomplete'){
  a=rand(20,40)*1000;b=rand(2,6)*1000;c=rand(4,9)*1000;
  if(v===0)q=N('Reconstruct credit sales',`Opening receivables ${money(b)}; closing receivables ${money(c)}; customer receipts ${money(a)}; sales returns ${money(500)}. There are no other movements and all sales are on credit. Ignore VAT. Find credit sales.`,a+500+c-b,`Opening receivables + sales − receipts − returns = closing receivables. Sales = ${money(a)} + ${money(500)} + ${money(c)} − ${money(b)} = ${money(a+500+c-b)}.`, '£',{a,b,c,formula:'sales'});
  if(v===1)q=N('Reconstruct credit purchases',`Opening payables ${money(b)}; closing payables ${money(c)}; supplier payments ${money(a)}; purchase returns ${money(300)}. No other movements; all purchases are on credit. Ignore VAT. Find credit purchases.`,a+300+c-b,`Purchases = supplier payments + purchase returns + closing payables − opening payables = ${money(a+300+c-b)}.`, '£',{a,b,c,formula:'purchases'});
  if(v===2)q=N('Find profit from capital',`Opening capital ${money(a)}; closing capital ${money(a+c)}; drawings ${money(b)}; additional capital introduced ${money(1000)}. Calculate profit for the year.`,c+b-1000,`Profit = closing capital − opening capital + drawings − capital introduced = ${money(c+b-1000)}.`, '£',{a:c,b,c:1000,formula:'summinus'});
  if(v===3){let markup=[20,25,50][rand(0,2)];q=N('Mark-up versus margin',`Cost of sales is ${money(a)} and gross profit is ${markup}% of cost of sales (mark-up). Calculate sales revenue.`,a*(1+markup/100),`Gross profit = ${money(a)} × ${markup}% = ${money(a*markup/100)}. Sales = cost + gross profit = ${money(a*(1+markup/100))}. Mark-up uses cost, not sales.`, '£',{a,d:markup,formula:'markup'})}
 }
 if(id==='ratios'){
  a=rand(40,90)*1000;b=rand(10,25)*1000;c=rand(3,8)*1000;
  let types=['Gross profit margin','Net profit margin','ROCE','Expense / sales revenue percentage'];
  if(rand(0,4)===4)q=C('Interpret a ratio','A business’s selling price stays unchanged while the purchase cost per unit falls. Sales mix and all other factors are unchanged. What happens to gross profit margin?','It increases',['It decreases','It stays unchanged','It must become negative'],'Lower unit cost increases gross profit for the same sales revenue, so gross profit margin increases.');
  else if(v===2){let loan=rand(5,20)*1000;q=N('Calculate ROCE',`Profit for the year is ${money(c)}. Capital is ${money(a)} and non-current liabilities are ${money(loan)}. Calculate ROCE to two decimal places.`,c/(a+loan)*100,`Capital employed = ${money(a)} + ${money(loan)} = ${money(a+loan)}. ROCE = ${money(c)} ÷ ${money(a+loan)} × 100 = ${(c/(a+loan)*100).toFixed(2)}%.`, '%',{a:c,b:a+loan,formula:'ratio'})}
  else {let numerator=v===0?b:c;q=N(types[v],`Sales revenue is ${money(a)}. ${v===0?'Gross profit':v===1?'Profit for the year':'Rent expense'} is ${money(numerator)}. Calculate ${types[v].toLowerCase()} to two decimal places.`,numerator/a*100,`${money(numerator)} ÷ sales revenue ${money(a)} × 100 = ${(numerator/a*100).toFixed(2)}%.`, '%',{a:numerator,b:a,formula:'ratio'})}
 }
 if(id==='sole'){
  a=rand(40,80)*1000;b=rand(15,25)*1000;c=rand(2,8)*1000;
  if(v===0)q=N('Calculate cost of sales',`Opening inventory ${money(c)}; purchases ${money(b)}; purchase returns ${money(600)}; carriage inwards ${money(300)}; closing inventory ${money(2000)}. Calculate cost of sales.`,c+b-600+300-2000,`Net purchases = ${money(b)} − ${money(600)} + ${money(300)}. Cost of sales = opening inventory + net purchases − closing inventory = ${money(c+b-2300)}.`, '£',{a:c,b,c:2300,formula:'summinus'});
  if(v===1)q=N('Calculate profit',`Sales revenue ${money(a)}; cost of sales ${money(b)}; expenses ${money(c)}. There is no other income. Calculate profit for the year.`,a-b-c,`Gross profit = ${money(a-b)}. Less expenses ${money(c)} gives profit ${money(a-b-c)}.`, '£',{a,b,c,formula:'subtract'});
  if(v===2)q=N('Calculate closing capital',`Opening capital ${money(a)}; capital introduced ${money(1000)}; profit ${money(c)}; drawings ${money(b)}. Find closing capital.`,a+1000+c-b,`Closing capital = opening capital + capital introduced + profit − drawings = ${money(a+1000+c-b)}.`, '£',{a,b,c,formula:'capital'});
  if(v===3)q=N('SFP: net assets',`Non-current assets ${money(a)}; current assets ${money(b)}; current liabilities ${money(c)}; non-current liabilities ${money(10000)}. Calculate net assets in the SFP.`,a+b-c-10000,`Net assets = non-current assets + current assets − current liabilities − non-current liabilities = ${money(a+b-c-10000)}.`, '£',{a,b,c,formula:'netassets'});
 }
 if(id==='partnership'){
  a=rand(30,70)*1000;b=rand(2,5)*1000;c=rand(1,3)*1000;
  if(v===0){let residual=a+1000-b-c-5000;q=N('Appropriate residual profit',`Partnership profit is ${money(a)}. Total interest on drawings ${money(1000)}; total interest on capital ${money(b)}; partner A salary ${money(5000)}; partner B salary ${money(c)}. Residual profit is shared A:B = 3:2. Calculate A’s share of residual profit only.`,residual*3/5,`Residual profit = ${money(a)} + ${money(1000)} − ${money(b)} − ${money(5000)} − ${money(c)} = ${money(residual)}. A’s share = 3/5 × residual = ${money(residual*3/5)}.`, '£',{a,b,c,formula:'appropriation'})}
  if(v===1)q=N('Partner current account',`A partner has an opening current account credit of ${money(b)}, salary ${money(c)}, interest on capital ${money(800)}, residual profit share ${money(6000)}, drawings ${money(4000)} and interest on drawings ${money(200)}. Find the closing credit balance.`,b+c+800+6000-4000-200,`Add salary, interest on capital and profit share; deduct drawings and interest on drawings: closing credit ${money(b+c+2600)}.`, '£',{a:b,b:c,c:2600,formula:'sum'});
  if(v===2)q=C('Partner salary treatment','How is a partner’s salary treated in partnership accounts?','As an appropriation of profit',['As a wages expense reducing partnership profit','As an irrecoverable debt','As a bank reconciliation timing difference'],'A partner’s salary is an agreed allocation of profit, rather than an employee wage expense.');
  if(v===3)q=C('Capital and current accounts','Under a fixed-capital system, where are drawings and routine profit appropriations recorded?','Partners’ current accounts',['Partners’ fixed capital accounts','Sales ledger control account','Bank reconciliation statement'],'Fixed capital records capital contributions. Routine appropriations and drawings are recorded in current accounts.');
 }
 if(id==='double'){
  if(v===0)q=N('Accounting equation',`Assets total ${money(a)} and liabilities total ${money(b)}. What is capital?`,a-b,`Assets = capital + liabilities, so capital = ${money(a)} − ${money(b)} = ${money(a-b)}.`, '£',{a,b,formula:'difference'});
  if(v===1)q=C('Credit purchase journal',`An unpaid invoice of ${money(b)} is received for goods bought for resale. Ignore VAT. Which journal is correct?`,'Debit purchases; credit payables ledger control account',['Debit inventory; credit sales','Debit bank; credit purchases','Debit payables ledger control account; credit purchases'],'Under the periodic approach, goods bought for resale are debited to purchases. The unpaid invoice creates a payable.');
  if(v===2)q=C('Customer payment journal',`A customer pays ${money(b)} against an invoice already recorded. Which journal is correct?`,'Debit bank; credit receivables ledger control account',['Debit bank; credit sales again','Debit receivables ledger control account; credit bank','Debit sales; credit bank'],'Bank increases and the existing receivable decreases. Do not recognise the sale twice.');
  if(v===3)q=C('Account classification','Which account is normally a current liability?','Payables ledger control account',['Equipment','Prepaid expense','Drawings'],'Trade payables are normally amounts due to suppliers within the normal operating cycle.');
 }
 if(id==='incomplete'&&v===3&&rand(0,1)){let margin=[20,25,40][rand(0,2)];q=N('Margin versus mark-up',`Cost of sales is ${money(a)}. Gross profit margin is ${margin}% of sales revenue. Calculate sales revenue.`,a/(1-margin/100),`Cost of sales is ${100-margin}% of sales revenue. Sales = ${money(a)} ÷ ${100-margin}% = ${money(a/(1-margin/100))}. Margin is based on sales, unlike mark-up.`, '£',{a,d:margin,formula:'margin'})}
 if(!q)throw Error('No question for '+id);return q;
}
